/**
 * General-N turnover-constrained long-only Markowitz reference solver.
 *
 * This isolated staging implementation solves
 *   maximize mu·w - lambdaRisk * wᵀ Sigma w
 *   subject to w >= 0, sum(w) = 1, 0.5*||w-w0||1 <= tau.
 *
 * The projection is onto the simplex intersected with the L1 ball; it does
 * not clip weights and silently renormalize them.  The returned certificate
 * is a projected-KKT residual.  A max-iteration result is never optimal.
 */

export const COMPARISON_ABSOLUTE_TOLERANCE = 1e-9;
export const COMPARISON_RELATIVE_TOLERANCE = 1e-8;
export const FEASIBILITY_TOLERANCE = 1e-10;
export const CURRENT_SUM_TOLERANCE = 1e-12;
export const PSD_RELATIVE_TOLERANCE = 1e-10;
export const STATIONARITY_TOLERANCE = 1e-8;
export const PROJECTION_BISECTION_ITERATIONS = 60;
export const DEFAULT_MAX_ITERATIONS = 5000;

